pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 am) public {
        vm.assume(user != address(0));
        uint256 totalBalance = c.MinSum() + 1 ether; // ensure enough balance
        vm.deal(address(c), totalBalance);
        // Simulate a put to create balance for user
        vm.prank(user);
        c.Put{value: totalBalance}(block.timestamp + 1);
        // Bound am to valid range
        am = bound(am, 0, totalBalance);
        // Record total contract balance before collect
        uint256 contractBalanceBefore = address(c).balance;
        // Perform Collect
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));
        // General rule: after Collect, total balance of all accounts <= contract balance
        // We check: the sum of all account balances (from public mapping) <= contract balance
        // But mapping is not iterable; we use the known user's balance and the fact that only one account is modified.
        // Simpler: the contract balance after collect should be >= 0 (always true) and the user's balance should never increase beyond what was put in.
        // The invariant: user's balance after collect <= totalBalance - (contractBalanceBefore - address(c).balance)
        // Actually simpler: the contract balance after collect should equal contractBalanceBefore - am (if successful) or stay (if reverted).
        // We assert that the contract balance never goes negative (implicitly always true) and that the sum of all balances never exceeds contract balance.
        // Since only user's balance changes, the invariant is: c.Acc(user).balance + (address(c).balance - (contractBalanceBefore - c.Acc(user).balance)) == contractBalanceBefore? No.
        // Best general rule: the contract's ether balance is always >= 0 (trivially true) but we need a real assert.
        // Use: after collect, the sum of all account balances (approximated by c.MinSum() and user's balance) is <= contract balance.
        // We can't iterate, but we know the only account with balance is user, so: c.Acc(user).balance <= address(c).balance.
        assertTrue(c.Acc(user).balance <= address(c).balance, "Account balance exceeds contract balance");
    }
}

