        uint256 senderBalanceBefore = c.Acc(sender).balance;

        // Call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Record balance after Collect
        uint256 balanceAfter = address(c).balance;
        uint256 senderBalanceAfter = c.Acc(sender).balance;

        // Rule: If Collect succeeded, the ether taken from the contract (balanceBefore - balanceAfter) equals the sum of amount deducted from sender's balance (senderBalanceBefore - senderBalanceAfter)
